const updateAutomationMeta = `-- name: UpdateAutomationMeta :one
UPDATE automations SET name = $1, description = $2, updated_by = $3, updated_at = now()
WHERE id = $4
RETURNING id, workspace_id, name, description, status, template_key, live_version, draft_version, trigger, created_by, created_at, updated_at, deleted_at, paused_at, paused_by, pause_reason, draft_revision, updated_by
`

type UpdateAutomationMetaParams struct {
	Name        string     `json:"name"`
	Description string     `json:"description"`
	UpdatedBy   *uuid.UUID `json:"updatedBy"`
	ID          uuid.UUID  `json:"id"`
}

func (q *Queries) UpdateAutomationMeta(ctx context.Context, arg UpdateAutomationMetaParams) (Automation, error) {
	row := q.db.QueryRow(ctx, updateAutomationMeta,
		arg.Name,
		arg.Description,
		arg.UpdatedBy,
		arg.ID,
	)
	var i Automation
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Status,
		&i.TemplateKey,
		&i.LiveVersion,
		&i.DraftVersion,
		&i.Trigger,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.PausedAt,
		&i.PausedBy,
		&i.PauseReason,
		&i.DraftRevision,
		&i.UpdatedBy,
	)
	return i, err
}

